import ast,os,collections
def defs(t):
    return [n.name for n in t.body if isinstance(n,(ast.FunctionDef,ast.ClassDef))]
orig=collections.Counter(defs(ast.parse(open('/tmp/orig/reports_orig.py').read())))
new=collections.Counter()
for dp,dn,fn in os.walk('tally/reports'):
    for f in fn:
        if f.endswith('.py'): new.update(defs(ast.parse(open(os.path.join(dp,f)).read())))
print(orig==new, len(orig), len(new))
EOF
